25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream XGMII frame receiver (XGMII in, AXI out)
33	 */
34	module axis_xgmii_rx_64 #
35	(
36	    parameter DATA_WIDTH = 64,
37	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
38	    parameter CTRL_WIDTH = (DATA_WIDTH/8),
39	    parameter PTP_TS_ENABLE = 0,
40	    parameter PTP_TS_FMT_TOD = 1,
41	    parameter PTP_TS_WIDTH = PTP_TS_FMT_TOD ? 96 : 64,
42	    parameter USER_WIDTH = (PTP_TS_ENABLE ? PTP_TS_WIDTH : 0) + 1
43	)
44	(
45	    input  wire                     clk,
46	    input  wire                     rst,
47	
48	    /*
49	     * XGMII input
50	     */
51	    input  wire [DATA_WIDTH-1:0]    xgmii_rxd,
52	    input  wire [CTRL_WIDTH-1:0]    xgmii_rxc,
53	
54	    /*
55	     * AXI output
56	     */
57	    output wire [DATA_WIDTH-1:0]    m_axis_tdata,
58	    output wire [KEEP_WIDTH-1:0]    m_axis_tkeep,
59	    output wire                     m_axis_tvalid,
60	    output wire                     m_axis_tlast,
61	    output wire [USER_WIDTH-1:0]    m_axis_tuser,
62	
63	    /*
64	     * PTP
65	     */
66	    input  wire [PTP_TS_WIDTH-1:0]  ptp_ts,
67	
68	    /*
69	     * Configuration
70	     */
71	    input  wire                     cfg_rx_enable,
72	
73	    /*
74	     * Status
75	     */
76	    output wire [1:0]               start_packet,
77	    output wire                     error_bad_frame,
78	    output wire                     error_bad_fcs
79	);
80	
81	// bus width assertions
82	initial begin
83	    if (DATA_WIDTH != 64) begin
84	        $error("Error: Interface width must be 64");
85	        $finish;
86	    end
87	
88	    if (KEEP_WIDTH * 8 != DATA_WIDTH || CTRL_WIDTH * 8 != DATA_WIDTH) begin
89	        $error("Error: Interface requires byte (8-bit) granularity");
90	        $finish;
91	    end
92	end
93	
94	localparam [7:0]
95	    ETH_PRE = 8'h55,
96	    ETH_SFD = 8'hD5;
97	
98	localparam [7:0]
99	    XGMII_IDLE = 8'h07,
100	    XGMII_START = 8'hfb,
101	    XGMII_TERM = 8'hfd,
102	    XGMII_ERROR = 8'hfe;
103	
104	localparam [1:0]
105	    STATE_IDLE = 2'd0,
106	    STATE_PAYLOAD = 2'd1,
107	    STATE_LAST = 2'd2;
108	
109	reg [1:0] state_reg = STATE_IDLE, state_next;
110	
111	// datapath control signals
112	reg reset_crc;
113	
114	reg lanes_swapped = 1'b0;
115	reg [31:0] swap_rxd = 32'd0;
116	reg [3:0] swap_rxc = 4'd0;
117	reg [3:0] swap_rxc_term = 4'd0;
118	
119	reg [DATA_WIDTH-1:0] xgmii_rxd_masked = {DATA_WIDTH{1'b0}};
120	reg [CTRL_WIDTH-1:0] xgmii_term = {CTRL_WIDTH{1'b0}};
121	reg [2:0] term_lane_reg = 0, term_lane_d0_reg = 0;
122	reg term_present_reg = 1'b0;
123	reg framing_error_reg = 1'b0, framing_error_d0_reg = 1'b0;
124	
125	reg [DATA_WIDTH-1:0] xgmii_rxd_d0 = {DATA_WIDTH{1'b0}};
126	reg [DATA_WIDTH-1:0] xgmii_rxd_d1 = {DATA_WIDTH{1'b0}};
127	
128	reg [CTRL_WIDTH-1:0] xgmii_rxc_d0 = {CTRL_WIDTH{1'b0}};
129	
130	reg xgmii_start_swap = 1'b0;
131	reg xgmii_start_d0 = 1'b0;
132	reg xgmii_start_d1 = 1'b0;
133	
134	reg [DATA_WIDTH-1:0] m_axis_tdata_reg = {DATA_WIDTH{1'b0}}, m_axis_tdata_next;
135	reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg = {KEEP_WIDTH{1'b0}}, m_axis_tkeep_next;
136	reg m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
137	reg m_axis_tlast_reg = 1'b0, m_axis_tlast_next;
138	reg [USER_WIDTH-1:0] m_axis_tuser_reg = {USER_WIDTH{1'b0}}, m_axis_tuser_next;
139	
140	reg [1:0] start_packet_reg = 2'b00;
141	reg error_bad_frame_reg = 1'b0, error_bad_frame_next;
142	reg error_bad_fcs_reg = 1'b0, error_bad_fcs_next;
143	
144	reg [PTP_TS_WIDTH-1:0] ptp_ts_reg = 0;
145	reg [PTP_TS_WIDTH-1:0] ptp_ts_adj_reg = 0;
146	reg ptp_ts_borrow_reg = 0;
147	
148	reg [31:0] crc_state = 32'hFFFFFFFF;
149	
150	wire [31:0] crc_next;
151	
152	wire [7:0] crc_valid;
153	reg [7:0] crc_valid_save;
154	
155	assign crc_valid[7] = crc_next == ~32'h2144df1c;
156	assign crc_valid[6] = crc_next == ~32'hc622f71d;
157	assign crc_valid[5] = crc_next == ~32'hb1c2a1a3;
158	assign crc_valid[4] = crc_next == ~32'h9d6cdf7e;
159	assign crc_valid[3] = crc_next == ~32'h6522df69;
160	assign crc_valid[2] = crc_next == ~32'he60914ae;
161	assign crc_valid[1] = crc_next == ~32'he38a6876;
162	assign crc_valid[0] = crc_next == ~32'h6b87b1ec;
163	
164	reg [4+16-1:0] last_ts_reg = 0;
165	reg [4+16-1:0] ts_inc_reg = 0;
166	
167	assign m_axis_tdata = m_axis_tdata_reg;
168	assign m_axis_tkeep = m_axis_tkeep_reg;
169	assign m_axis_tvalid = m_axis_tvalid_reg;
170	assign m_axis_tlast = m_axis_tlast_reg;
171	assign m_axis_tuser = m_axis_tuser_reg;
172	
173	assign start_packet = start_packet_reg;
174	assign error_bad_frame = error_bad_frame_reg;
175	assign error_bad_fcs = error_bad_fcs_reg;
176	
177	lfsr #(
178	    .LFSR_WIDTH(32),
179	    .LFSR_POLY(32'h4c11db7),
180	    .LFSR_CONFIG("GALOIS"),
181	    .LFSR_FEED_FORWARD(0),
182	    .REVERSE(1),
183	    .DATA_WIDTH(64),
184	    .STYLE("AUTO")
185	)
186	eth_crc (
187	    .data_in(xgmii_rxd_d0),
188	    .state_in(crc_state),
189	    .data_out(),
190	    .state_out(crc_next)
191	);
192	
193	// Mask input data
194	integer j;
195	
196	always @* begin
197	    for (j = 0; j < 8; j = j + 1) begin
198	        xgmii_rxd_masked[j*8 +: 8] = xgmii_rxc[j] ? 8'd0 : xgmii_rxd[j*8 +: 8];
199	        xgmii_term[j] = xgmii_rxc[j] && (xgmii_rxd[j*8 +: 8] == XGMII_TERM);
200	    end
201	end
202	
203	always @* begin
204	    state_next = STATE_IDLE;
205	
206	    reset_crc = 1'b0;
207	
208	    m_axis_tdata_next = xgmii_rxd_d1;
209	    m_axis_tkeep_next = {KEEP_WIDTH{1'b1}};
210	    m_axis_tvalid_next = 1'b0;
211	    m_axis_tlast_next = 1'b0;
212	    m_axis_tuser_next = m_axis_tuser_reg;
213	    m_axis_tuser_next[0] = 1'b0;
214	
215	    error_bad_frame_next = 1'b0;
216	    error_bad_fcs_next = 1'b0;
217	
218	    case (state_reg)
219	        STATE_IDLE: begin
220	            // idle state - wait for packet
221	            reset_crc = 1'b1;
222	
223	            if (xgmii_start_d1 && cfg_rx_enable) begin
224	                // start condition
225	
226	                reset_crc = 1'b0;
227	                state_next = STATE_PAYLOAD;
228	            end else begin
229	                state_next = STATE_IDLE;
230	            end
231	        end
232	        STATE_PAYLOAD: begin
233	            // read payload
234	            m_axis_tdata_next = xgmii_rxd_d1;
235	            m_axis_tkeep_next = {KEEP_WIDTH{1'b1}};
236	            m_axis_tvalid_next = 1'b1;
237	            m_axis_tlast_next = 1'b0;
238	            m_axis_tuser_next[0] = 1'b0;
239	
240	            if (PTP_TS_ENABLE) begin
241	                m_axis_tuser_next[1 +: PTP_TS_WIDTH] = (!PTP_TS_FMT_TOD || ptp_ts_borrow_reg) ? ptp_ts_reg : ptp_ts_adj_reg;
242	            end
243	
244	            if (framing_error_reg || framing_error_d0_reg) begin
245	                // control or error characters in packet
246	                m_axis_tlast_next = 1'b1;
247	                m_axis_tuser_next[0] = 1'b1;
248	                error_bad_frame_next = 1'b1;
249	                reset_crc = 1'b1;
250	                state_next = STATE_IDLE;
251	            end else if (term_present_reg) begin
252	                reset_crc = 1'b1;
253	                if (term_lane_reg <= 4) begin
254	                    // end this cycle
255	                    m_axis_tkeep_next = {KEEP_WIDTH{1'b1}} >> (CTRL_WIDTH-4-term_lane_reg);
256	                    m_axis_tlast_next = 1'b1;
257	                    if ((term_lane_reg == 0 && crc_valid_save[7]) ||
258	                        (term_lane_reg == 1 && crc_valid[0]) ||
259	                        (term_lane_reg == 2 && crc_valid[1]) ||
260	                        (term_lane_reg == 3 && crc_valid[2]) ||
261	                        (term_lane_reg == 4 && crc_valid[3])) begin
262	                        // CRC valid
263	                    end else begin
264	                        m_axis_tuser_next[0] = 1'b1;
265	                        error_bad_frame_next = 1'b1;
266	                        error_bad_fcs_next = 1'b1;
267	                    end
268	                    state_next = STATE_IDLE;
269	                end else begin
270	                    // need extra cycle
271	                    state_next = STATE_LAST;
272	                end
273	            end else begin
274	                state_next = STATE_PAYLOAD;
275	            end
276	        end
277	        STATE_LAST: begin
278	            // last cycle of packet
279	            m_axis_tdata_next = xgmii_rxd_d1;
280	            m_axis_tkeep_next = {KEEP_WIDTH{1'b1}} >> (CTRL_WIDTH+4-term_lane_d0_reg);
281	            m_axis_tvalid_next = 1'b1;
282	            m_axis_tlast_next = 1'b1;
283	            m_axis_tuser_next[0] = 1'b0;
284	
285	            reset_crc = 1'b1;
286	
287	            if ((term_lane_d0_reg == 5 && crc_valid_save[4]) ||
288	                (term_lane_d0_reg == 6 && crc_valid_save[5]) ||
289	                (term_lane_d0_reg == 7 && crc_valid_save[6])) begin
290	                // CRC valid
291	            end else begin
292	                m_axis_tuser_next[0] = 1'b1;
293	                error_bad_frame_next = 1'b1;
294	                error_bad_fcs_next = 1'b1;
295	            end
296	
297	            if (xgmii_start_d1 && cfg_rx_enable) begin
298	                // start condition
299	
300	                reset_crc = 1'b0;
301	                state_next = STATE_PAYLOAD;
302	            end else begin
303	                state_next = STATE_IDLE;
304	            end
305	        end
306	    endcase
307	end
308	
309	integer i;
310	
311	always @(posedge clk) begin
312	    state_reg <= state_next;
313	
314	    m_axis_tdata_reg <= m_axis_tdata_next;
315	    m_axis_tkeep_reg <= m_axis_tkeep_next;
316	    m_axis_tvalid_reg <= m_axis_tvalid_next;
317	    m_axis_tlast_reg <= m_axis_tlast_next;
318	    m_axis_tuser_reg <= m_axis_tuser_next;
319	
320	    start_packet_reg <= 2'b00;
321	    error_bad_frame_reg <= error_bad_frame_next;
322	    error_bad_fcs_reg <= error_bad_fcs_next;
323	
324	    swap_rxd <= xgmii_rxd_masked[63:32];
325	    swap_rxc <= xgmii_rxc[7:4];
326	    swap_rxc_term <= xgmii_term[7:4];
327	
328	    xgmii_start_swap <= 1'b0;
329	    xgmii_start_d0 <= xgmii_start_swap;
330	
331	    if (PTP_TS_ENABLE && PTP_TS_FMT_TOD) begin
332	        // ns field rollover
333	        ptp_ts_adj_reg[15:0] <= ptp_ts_reg[15:0];
334	        {ptp_ts_borrow_reg, ptp_ts_adj_reg[45:16]} <= $signed({1'b0, ptp_ts_reg[45:16]}) - $signed(31'd1000000000);
335	        ptp_ts_adj_reg[47:46] <= 0;
336	        ptp_ts_adj_reg[95:48] <= ptp_ts_reg[95:48] + 1;
337	    end
338	
339	    // lane swapping and termination character detection
340	    if (lanes_swapped) begin
341	        xgmii_rxd_d0 <= {xgmii_rxd_masked[31:0], swap_rxd};
342	        xgmii_rxc_d0 <= {xgmii_rxc[3:0], swap_rxc};
343	
344	        term_lane_reg <= 0;
345	        term_present_reg <= 1'b0;
346	        framing_error_reg <= {xgmii_rxc[3:0], swap_rxc} != 0;
347	
348	        for (i = CTRL_WIDTH-1; i >= 0; i = i - 1) begin
349	            if ({xgmii_term[3:0], swap_rxc_term} & (1 << i)) begin
350	                term_lane_reg <= i;
351	                term_present_reg <= 1'b1;
352	                framing_error_reg <= ({xgmii_rxc[3:0], swap_rxc} & ({CTRL_WIDTH{1'b1}} >> (CTRL_WIDTH-i))) != 0;
353	                lanes_swapped <= 1'b0;
354	            end
355	        end
356	    end else begin
357	        xgmii_rxd_d0 <= xgmii_rxd_masked;
358	        xgmii_rxc_d0 <= xgmii_rxc;
359	
360	        term_lane_reg <= 0;
361	        term_present_reg <= 1'b0;
362	        framing_error_reg <= xgmii_rxc != 0;
363	
364	        for (i = CTRL_WIDTH-1; i >= 0; i = i - 1) begin
365	            if (xgmii_rxc[i] && (xgmii_rxd[i*8 +: 8] == XGMII_TERM)) begin
366	                term_lane_reg <= i;
367	                term_present_reg <= 1'b1;
368	                framing_error_reg <= (xgmii_rxc & ({CTRL_WIDTH{1'b1}} >> (CTRL_WIDTH-i))) != 0;
369	                lanes_swapped <= 1'b0;
370	            end
371	        end
372	    end
373	
374	    // start control character detection
375	    if (xgmii_rxc[0] && xgmii_rxd[7:0] == XGMII_START) begin
376	        lanes_swapped <= 1'b0;
377	
378	        xgmii_start_d0 <= 1'b1;
379	
380	        term_lane_reg <= 0;
381	        term_present_reg <= 1'b0;
382	        framing_error_reg <= xgmii_rxc[7:1] != 0;
383	    end else if (xgmii_rxc[4] && xgmii_rxd[39:32] == XGMII_START) begin
384	        lanes_swapped <= 1'b1;
385	
386	        xgmii_start_swap <= 1'b1;
387	
388	        term_lane_reg <= 0;
389	        term_present_reg <= 1'b0;
390	        framing_error_reg <= xgmii_rxc[7:5] != 0;
391	    end
392	
393	    // capture timestamps
394	    if (xgmii_start_swap) begin
395	        start_packet_reg <= 2'b10;
396	        if (PTP_TS_FMT_TOD) begin
397	            ptp_ts_reg[45:0] <= ptp_ts[45:0] + (ts_inc_reg >> 1);
398	            ptp_ts_reg[95:48] <= ptp_ts[95:48];
399	        end else begin
400	            ptp_ts_reg <= ptp_ts + (ts_inc_reg >> 1);
401	        end
402	    end
403	
404	    if (xgmii_start_d0) begin
405	        if (!lanes_swapped) begin
406	            start_packet_reg <= 2'b01;
407	            ptp_ts_reg <= ptp_ts;
408	        end
409	    end
410	
411	    term_lane_d0_reg <= term_lane_reg;
412	    framing_error_d0_reg <= framing_error_reg;
413	
414	    if (reset_crc) begin
415	        crc_state <= 32'hFFFFFFFF;
416	    end else begin
417	        crc_state <= crc_next;
418	    end
419	
420	    crc_valid_save <= crc_valid;
421	
422	    xgmii_rxd_d1 <= xgmii_rxd_d0;
423	    xgmii_start_d1 <= xgmii_start_d0;
424	
425	    last_ts_reg <= ptp_ts;
426	    ts_inc_reg <= ptp_ts - last_ts_reg;
427	
428	    if (rst) begin
429	        state_reg <= STATE_IDLE;
430	
431	        m_axis_tvalid_reg <= 1'b0;
432	
433	        start_packet_reg <= 2'b00;
434	        error_bad_frame_reg <= 1'b0;
435	        error_bad_fcs_reg <= 1'b0;
436	
437	        xgmii_rxc_d0 <= {CTRL_WIDTH{1'b0}};
438	
439	        xgmii_start_swap <= 1'b0;
440	        xgmii_start_d0 <= 1'b0;
441	        xgmii_start_d1 <= 1'b0;
442	
443	        lanes_swapped <= 1'b0;
444	    end
445	end
446	
447	endmodule
448	
449	`resetall
450

