25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream XGMII frame receiver (XGMII in, AXI out)
33	 */
34	module axis_xgmii_rx_32 #
35	(
36	    parameter DATA_WIDTH = 32,
37	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
38	    parameter CTRL_WIDTH = (DATA_WIDTH/8),
39	    parameter PTP_TS_ENABLE = 0,
40	    parameter PTP_TS_WIDTH = 96,
41	    parameter USER_WIDTH = (PTP_TS_ENABLE ? PTP_TS_WIDTH : 0) + 1
42	)
43	(
44	    input  wire                     clk,
45	    input  wire                     rst,
46	
47	    /*
48	     * XGMII input
49	     */
50	    input  wire [DATA_WIDTH-1:0]    xgmii_rxd,
51	    input  wire [CTRL_WIDTH-1:0]    xgmii_rxc,
52	
53	    /*
54	     * AXI output
55	     */
56	    output wire [DATA_WIDTH-1:0]    m_axis_tdata,
57	    output wire [KEEP_WIDTH-1:0]    m_axis_tkeep,
58	    output wire                     m_axis_tvalid,
59	    output wire                     m_axis_tlast,
60	    output wire [USER_WIDTH-1:0]    m_axis_tuser,
61	
62	    /*
63	     * PTP
64	     */
65	    input  wire [PTP_TS_WIDTH-1:0]  ptp_ts,
66	
67	    /*
68	     * Configuration
69	     */
70	    input  wire                     cfg_rx_enable,
71	
72	    /*
73	     * Status
74	     */
75	    output wire                     start_packet,
76	    output wire                     error_bad_frame,
77	    output wire                     error_bad_fcs
78	);
79	
80	// bus width assertions
81	initial begin
82	    if (DATA_WIDTH != 32) begin
83	        $error("Error: Interface width must be 32");
84	        $finish;
85	    end
86	
87	    if (KEEP_WIDTH * 8 != DATA_WIDTH || CTRL_WIDTH * 8 != DATA_WIDTH) begin
88	        $error("Error: Interface requires byte (8-bit) granularity");
89	        $finish;
90	    end
91	end
92	
93	localparam [7:0]
94	    ETH_PRE = 8'h55,
95	    ETH_SFD = 8'hD5;
96	
97	localparam [7:0]
98	    XGMII_IDLE = 8'h07,
99	    XGMII_START = 8'hfb,
100	    XGMII_TERM = 8'hfd,
101	    XGMII_ERROR = 8'hfe;
102	
103	localparam [1:0]
104	    STATE_IDLE = 2'd0,
105	    STATE_PREAMBLE = 2'd1,
106	    STATE_PAYLOAD = 2'd2,
107	    STATE_LAST = 2'd3;
108	
109	reg [1:0] state_reg = STATE_IDLE, state_next;
110	
111	// datapath control signals
112	reg reset_crc;
113	
114	reg [1:0] term_lane_reg = 0, term_lane_d0_reg = 0;
115	reg term_present_reg = 1'b0;
116	reg framing_error_reg = 1'b0;
117	
118	reg [DATA_WIDTH-1:0] xgmii_rxd_d0 = {DATA_WIDTH{1'b0}};
119	reg [DATA_WIDTH-1:0] xgmii_rxd_d1 = {DATA_WIDTH{1'b0}};
120	reg [DATA_WIDTH-1:0] xgmii_rxd_d2 = {DATA_WIDTH{1'b0}};
121	
122	reg [CTRL_WIDTH-1:0] xgmii_rxc_d0 = {CTRL_WIDTH{1'b0}};
123	
124	reg xgmii_start_d0 = 1'b0;
125	reg xgmii_start_d1 = 1'b0;
126	reg xgmii_start_d2 = 1'b0;
127	
128	reg [DATA_WIDTH-1:0] m_axis_tdata_reg = {DATA_WIDTH{1'b0}}, m_axis_tdata_next;
129	reg [KEEP_WIDTH-1:0] m_axis_tkeep_reg = {KEEP_WIDTH{1'b0}}, m_axis_tkeep_next;
130	reg m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
131	reg m_axis_tlast_reg = 1'b0, m_axis_tlast_next;
132	reg [USER_WIDTH-1:0] m_axis_tuser_reg = {USER_WIDTH{1'b0}}, m_axis_tuser_next;
133	
134	reg start_packet_reg = 1'b0, start_packet_next;
135	reg error_bad_frame_reg = 1'b0, error_bad_frame_next;
136	reg error_bad_fcs_reg = 1'b0, error_bad_fcs_next;
137	
138	reg [31:0] crc_state = 32'hFFFFFFFF;
139	
140	wire [31:0] crc_next;
141	
142	wire [3:0] crc_valid;
143	reg [3:0] crc_valid_save;
144	
145	assign crc_valid[3] = crc_next == ~32'h2144df1c;
