65	     */
66	    output wire [DATA_WIDTH-1:0]     xgmii_txd,
67	    output wire [CTRL_WIDTH-1:0]     xgmii_txc,
68	
69	    /*
70	     * PTP
71	     */
72	    input  wire [PTP_TS_WIDTH-1:0]   ptp_ts,
73	    output wire [PTP_TS_WIDTH-1:0]   m_axis_ptp_ts,
74	    output wire [PTP_TAG_WIDTH-1:0]  m_axis_ptp_ts_tag,
75	    output wire                      m_axis_ptp_ts_valid,
76	
77	    /*
78	     * Configuration
79	     */
80	    input  wire [7:0]                cfg_ifg,
81	    input  wire                      cfg_tx_enable,
82	
83	    /*
84	     * Status
85	     */
86	    output wire                      start_packet,
87	    output wire                      error_underflow
88	);
89	
90	parameter EMPTY_WIDTH = $clog2(KEEP_WIDTH);
91	parameter MIN_LEN_WIDTH = $clog2(MIN_FRAME_LENGTH-4-CTRL_WIDTH+1);
92	
93	// bus width assertions
94	initial begin
95	    if (DATA_WIDTH != 32) begin
96	        $error("Error: Interface width must be 32");
97	        $finish;
98	    end
99	
100	    if (KEEP_WIDTH * 8 != DATA_WIDTH || CTRL_WIDTH * 8 != DATA_WIDTH) begin
101	        $error("Error: Interface requires byte (8-bit) granularity");
102	        $finish;
103	    end
104	end
105	
106	localparam [7:0]
107	    ETH_PRE = 8'h55,
108	    ETH_SFD = 8'hD5;
109	
110	localparam [7:0]
111	    XGMII_IDLE = 8'h07,
112	    XGMII_START = 8'hfb,
113	    XGMII_TERM = 8'hfd,
114	    XGMII_ERROR = 8'hfe;
115	
116	localparam [3:0]
117	    STATE_IDLE = 4'd0,
118	    STATE_PREAMBLE = 4'd1,
119	    STATE_PAYLOAD = 4'd2,
120	    STATE_PAD = 4'd3,
121	    STATE_FCS_1 = 4'd4,
122	    STATE_FCS_2 = 4'd5,
123	    STATE_FCS_3 = 4'd6,
124	    STATE_ERR = 4'd7,
125	    STATE_IFG = 4'd8;
126	
127	reg [3:0] state_reg = STATE_IDLE, state_next;
128	
129	// datapath control signals
130	reg reset_crc;
131	reg update_crc;
132	
133	reg [DATA_WIDTH-1:0] s_axis_tdata_masked;
134	
135	reg [DATA_WIDTH-1:0] s_tdata_reg = 0, s_tdata_next;
136	reg [EMPTY_WIDTH-1:0] s_empty_reg = 0, s_empty_next;
137	
138	reg [DATA_WIDTH-1:0] fcs_output_txd_0;
139	reg [DATA_WIDTH-1:0] fcs_output_txd_1;
140	reg [CTRL_WIDTH-1:0] fcs_output_txc_0;
141	reg [CTRL_WIDTH-1:0] fcs_output_txc_1;
142	
143	reg [7:0] ifg_offset;
144	
145	reg extra_cycle;
146	
147	reg frame_reg = 1'b0, frame_next;
148	reg frame_error_reg = 1'b0, frame_error_next;
149	reg [MIN_LEN_WIDTH-1:0] frame_min_count_reg = 0, frame_min_count_next;
150	
151	reg [7:0] ifg_count_reg = 8'd0, ifg_count_next;
152	reg [1:0] deficit_idle_count_reg = 2'd0, deficit_idle_count_next;
153	
154	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
155	
156	reg [PTP_TS_WIDTH-1:0] m_axis_ptp_ts_reg = 0, m_axis_ptp_ts_next;
157	reg [PTP_TAG_WIDTH-1:0] m_axis_ptp_ts_tag_reg = 0, m_axis_ptp_ts_tag_next;
158	reg m_axis_ptp_ts_valid_reg = 1'b0, m_axis_ptp_ts_valid_next;
159	
160	reg [31:0] crc_state_reg[3:0];
161	wire [31:0] crc_state_next[3:0];
162	
163	reg [DATA_WIDTH-1:0] xgmii_txd_reg = {CTRL_WIDTH{XGMII_IDLE}}, xgmii_txd_next;
164	reg [CTRL_WIDTH-1:0] xgmii_txc_reg = {CTRL_WIDTH{1'b1}}, xgmii_txc_next;
165	
166	reg start_packet_reg = 1'b0, start_packet_next;
167	reg error_underflow_reg = 1'b0, error_underflow_next;
168	
169	assign s_axis_tready = s_axis_tready_reg;
170	
171	assign xgmii_txd = xgmii_txd_reg;
172	assign xgmii_txc = xgmii_txc_reg;
173	
174	assign m_axis_ptp_ts = PTP_TS_ENABLE ? m_axis_ptp_ts_reg : 0;
175	assign m_axis_ptp_ts_tag = PTP_TAG_ENABLE ? m_axis_ptp_ts_tag_reg : 0;
176	assign m_axis_ptp_ts_valid = PTP_TS_ENABLE || PTP_TAG_ENABLE ? m_axis_ptp_ts_valid_reg : 1'b0;
177	
178	assign start_packet = start_packet_reg;
179	assign error_underflow = error_underflow_reg;
180	
181	generate
182	    genvar n;
183	
184	    for (n = 0; n < 4; n = n + 1) begin : crc
185	        lfsr #(
186	            .LFSR_WIDTH(32),
187	            .LFSR_POLY(32'h4c11db7),
188	            .LFSR_CONFIG("GALOIS"),
189	            .LFSR_FEED_FORWARD(0),
190	            .REVERSE(1),
191	            .DATA_WIDTH(8*(n+1)),
192	            .STYLE("AUTO")
193	        )
194	        eth_crc (
195	            .data_in(s_tdata_reg[0 +: 8*(n+1)]),
196	            .state_in(crc_state_reg[3]),
197	            .data_out(),
198	            .state_out(crc_state_next[n])
199	        );
200	    end
201	
202	endgenerate
203	
204	function [1:0] keep2empty;
205	    input [3:0] k;
206	    casez (k)
207	        4'bzzz0: keep2empty = 2'd3;
208	        4'bzz01: keep2empty = 2'd3;
209	        4'bz011: keep2empty = 2'd2;
210	        4'b0111: keep2empty = 2'd1;
211	        4'b1111: keep2empty = 2'd0;
212	    endcase
213	endfunction
214	
215	// Mask input data
216	integer j;
217	
218	always @* begin
219	    for (j = 0; j < 4; j = j + 1) begin
220	        s_axis_tdata_masked[j*8 +: 8] = s_axis_tkeep[j] ? s_axis_tdata[j*8 +: 8] : 8'd0;
221	    end
222	end
223	
224	// FCS cycle calculation
225	always @* begin
226	    casez (s_empty_reg)
227	        2'd3: begin
228	            fcs_output_txd_0 = {~crc_state_next[0][23:0], s_tdata_reg[7:0]};
229	            fcs_output_txd_1 = {{2{XGMII_IDLE}}, XGMII_TERM, ~crc_state_reg[0][31:24]};
230	            fcs_output_txc_0 = 4'b0000;
231	            fcs_output_txc_1 = 4'b1110;
232	            ifg_offset = 8'd3;
233	            extra_cycle = 1'b0;
234	        end
235	        2'd2: begin
236	            fcs_output_txd_0 = {~crc_state_next[1][15:0], s_tdata_reg[15:0]};
237	            fcs_output_txd_1 = {XGMII_IDLE, XGMII_TERM, ~crc_state_reg[1][31:16]};
238	            fcs_output_txc_0 = 4'b0000;
239	            fcs_output_txc_1 = 4'b1100;
240	            ifg_offset = 8'd2;
241	            extra_cycle = 1'b0;
242	        end
243	        2'd1: begin
244	            fcs_output_txd_0 = {~crc_state_next[2][7:0], s_tdata_reg[23:0]};
245	            fcs_output_txd_1 = {XGMII_TERM, ~crc_state_reg[2][31:8]};
246	            fcs_output_txc_0 = 4'b0000;
247	            fcs_output_txc_1 = 4'b1000;
248	            ifg_offset = 8'd1;
249	            extra_cycle = 1'b0;
250	        end
251	        2'd0: begin
252	            fcs_output_txd_0 = s_tdata_reg;
253	            fcs_output_txd_1 = ~crc_state_reg[3];
254	            fcs_output_txc_0 = 4'b0000;
255	            fcs_output_txc_1 = 4'b0000;
256	            ifg_offset = 8'd4;
257	            extra_cycle = 1'b1;
258	        end
259	    endcase
260	end
261	
262	always @* begin
263	    state_next = STATE_IDLE;
264	
265	    reset_crc = 1'b0;
266	    update_crc = 1'b0;
267	
268	    frame_next = frame_reg;
269	    frame_error_next = frame_error_reg;
270	    frame_min_count_next = frame_min_count_reg;
271	
272	    ifg_count_next = ifg_count_reg;
273	    deficit_idle_count_next = deficit_idle_count_reg;
274	
275	    s_axis_tready_next = 1'b0;
276	
277	    s_tdata_next = s_tdata_reg;
278	    s_empty_next = s_empty_reg;
279	
280	    m_axis_ptp_ts_next = m_axis_ptp_ts_reg;
281	    m_axis_ptp_ts_tag_next = m_axis_ptp_ts_tag_reg;
282	    m_axis_ptp_ts_valid_next = 1'b0;
283	
284	    if (start_packet_reg && PTP_TS_ENABLE) begin
285	        m_axis_ptp_ts_next = ptp_ts;
286	        if (PTP_TS_CTRL_IN_TUSER) begin
287	            m_axis_ptp_ts_tag_next = s_axis_tuser >> 2;
288	            m_axis_ptp_ts_valid_next = s_axis_tuser[1];
289	        end else begin
290	            m_axis_ptp_ts_tag_next = s_axis_tuser >> 1;
291	            m_axis_ptp_ts_valid_next = 1'b1;
292	        end
293	    end
294	
295	    // XGMII idle
296	    xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
297	    xgmii_txc_next = {CTRL_WIDTH{1'b1}};
298	
299	    start_packet_next = 1'b0;
300	    error_underflow_next = 1'b0;
301	
302	    if (s_axis_tvalid && s_axis_tready) begin
303	        frame_next = !s_axis_tlast;
304	    end
305	
306	    case (state_reg)
307	        STATE_IDLE: begin
308	            // idle state - wait for data
309	            frame_error_next = 1'b0;
310	            frame_min_count_next = MIN_FRAME_LENGTH-4-CTRL_WIDTH;
311	            reset_crc = 1'b1;
312	
313	            // XGMII idle
314	            xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
315	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
316	
317	            s_tdata_next = s_axis_tdata_masked;
318	            s_empty_next = keep2empty(s_axis_tkeep);
319	
320	            if (s_axis_tvalid && cfg_tx_enable) begin
321	                // XGMII start and preamble
322	                xgmii_txd_next = {{3{ETH_PRE}}, XGMII_START};
323	                xgmii_txc_next = 4'b0001;
324	                s_axis_tready_next = 1'b1;
325	                state_next = STATE_PREAMBLE;
326	            end else begin
327	                ifg_count_next = 8'd0;
328	                deficit_idle_count_next = 2'd0;
329	                state_next = STATE_IDLE;
330	            end
331	        end
332	        STATE_PREAMBLE: begin
333	            // send preamble
334	            reset_crc = 1'b1;
335	
336	            s_tdata_next = s_axis_tdata_masked;
337	            s_empty_next = keep2empty(s_axis_tkeep);
338	
339	            xgmii_txd_next = {ETH_SFD, {3{ETH_PRE}}};
340	            xgmii_txc_next = {CTRL_WIDTH{1'b0}};
341	
342	            s_axis_tready_next = 1'b1;
343	            start_packet_next = 1'b1;
344	            state_next = STATE_PAYLOAD;
345	        end
346	        STATE_PAYLOAD: begin
347	            // transfer payload
348	            update_crc = 1'b1;
349	            s_axis_tready_next = 1'b1;
350	
351	            if (frame_min_count_reg > CTRL_WIDTH) begin
352	                frame_min_count_next = frame_min_count_reg - CTRL_WIDTH;
353	            end else begin
354	                frame_min_count_next = 0;
355	            end
356	
357	            xgmii_txd_next = s_tdata_reg;
358	            xgmii_txc_next = {CTRL_WIDTH{1'b0}};
359	
360	            s_tdata_next = s_axis_tdata_masked;
361	            s_empty_next = keep2empty(s_axis_tkeep);
362	
363	            if (!s_axis_tvalid || s_axis_tlast) begin
364	                s_axis_tready_next = frame_next; // drop frame
365	                frame_error_next = !s_axis_tvalid || s_axis_tuser[0];
366	                error_underflow_next = !s_axis_tvalid;
367	
368	                if (ENABLE_PADDING && frame_min_count_reg) begin
369	                    if (frame_min_count_reg > CTRL_WIDTH) begin
370	                        s_empty_next = 0;
371	                        state_next = STATE_PAD;
372	                    end else begin
373	                        if (keep2empty(s_axis_tkeep) > CTRL_WIDTH-frame_min_count_reg) begin
374	                            s_empty_next = CTRL_WIDTH-frame_min_count_reg;
375	                        end
376	                        state_next = STATE_FCS_1;
377	                    end
378	                end else begin
379	                    state_next = STATE_FCS_1;
380	                end
381	            end else begin
382	                state_next = STATE_PAYLOAD;
383	            end
384	        end
385	        STATE_PAD: begin
386	            // pad frame to MIN_FRAME_LENGTH
387	            s_axis_tready_next = frame_next; // drop frame
388	
389	            xgmii_txd_next = s_tdata_reg;
390	            xgmii_txc_next = {CTRL_WIDTH{1'b0}};
391	
392	            s_tdata_next = 32'd0;
393	            s_empty_next = 0;
394	
395	            update_crc = 1'b1;
396	
397	            if (frame_min_count_reg > CTRL_WIDTH) begin
398	                frame_min_count_next = frame_min_count_reg - CTRL_WIDTH;
399	                state_next = STATE_PAD;
400	            end else begin
401	                frame_min_count_next = 0;
402	                s_empty_next = CTRL_WIDTH-frame_min_count_reg;
403	                state_next = STATE_FCS_1;
404	            end
405	        end
406	        STATE_FCS_1: begin
407	            // last cycle
408	            s_axis_tready_next = frame_next; // drop frame
409	
410	            xgmii_txd_next = fcs_output_txd_0;
411	            xgmii_txc_next = fcs_output_txc_0;
412	
413	            update_crc = 1'b1;
414	
415	            ifg_count_next = (cfg_ifg > 8'd12 ? cfg_ifg : 8'd12) - ifg_offset + deficit_idle_count_reg;
416	            if (frame_error_reg) begin
417	                state_next = STATE_ERR;
418	            end else begin
419	                state_next = STATE_FCS_2;
420	            end
421	        end
422	        STATE_FCS_2: begin
423	            // last cycle
424	            s_axis_tready_next = frame_next; // drop frame
425	
426	            xgmii_txd_next = fcs_output_txd_1;
427	            xgmii_txc_next = fcs_output_txc_1;
428	
429	            if (extra_cycle) begin
430	                state_next = STATE_FCS_3;
431	            end else begin
432	                state_next = STATE_IFG;
433	            end
434	        end
435	        STATE_FCS_3: begin
436	            // last cycle
437	            s_axis_tready_next = frame_next; // drop frame
438	
439	            xgmii_txd_next = {{3{XGMII_IDLE}}, XGMII_TERM};
440	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
441	
442	            if (ENABLE_DIC) begin
443	                if (ifg_count_next > 8'd3) begin
444	                    state_next = STATE_IFG;
445	                end else begin
446	                    deficit_idle_count_next = ifg_count_next;
447	                    ifg_count_next = 8'd0;
448	                    s_axis_tready_next = 1'b1;
449	                    state_next = STATE_IDLE;
450	                end
451	            end else begin
452	                if (ifg_count_next > 8'd0) begin
453	                    state_next = STATE_IFG;
454	                end else begin
455	                    state_next = STATE_IDLE;
456	                end
457	            end
458	        end
459	        STATE_ERR: begin
460	            // terminate packet with error
461	            s_axis_tready_next = frame_next; // drop frame
462	
463	            // XGMII error
464	            xgmii_txd_next = {XGMII_TERM, {3{XGMII_ERROR}}};
465	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
466	
467	            ifg_count_next = 8'd12;
468	
469	            state_next = STATE_IFG;
470	        end
471	        STATE_IFG: begin
472	            // send IFG
473	            s_axis_tready_next = frame_next; // drop frame
474	
475	            // XGMII idle
476	            xgmii_txd_next = {CTRL_WIDTH{XGMII_IDLE}};
477	            xgmii_txc_next = {CTRL_WIDTH{1'b1}};
478	
479	            if (ifg_count_reg > 8'd4) begin
480	                ifg_count_next = ifg_count_reg - 8'd4;
481	            end else begin
482	                ifg_count_next = 8'd0;
483	            end
484	
485	            if (ENABLE_DIC) begin
486	                if (ifg_count_next > 8'd3 || frame_reg) begin
487	                    state_next = STATE_IFG;
488	                end else begin
489	                    deficit_idle_count_next = ifg_count_next;
490	                    ifg_count_next = 8'd0;
491	                    state_next = STATE_IDLE;
492	                end
493	            end else begin
494	                if (ifg_count_next > 8'd0 || frame_reg) begin
495	                    state_next = STATE_IFG;
496	                end else begin
497	                    state_next = STATE_IDLE;
498	                end
499	            end
500	        end
501	    endcase
502	end
503	
504	always @(posedge clk) begin
505	    state_reg <= state_next;
506	
507	    frame_reg <= frame_next;
508	    frame_error_reg <= frame_error_next;
509	    frame_min_count_reg <= frame_min_count_next;
510	
511	    ifg_count_reg <= ifg_count_next;
512	    deficit_idle_count_reg <= deficit_idle_count_next;
513	
514	    s_tdata_reg <= s_tdata_next;
515	    s_empty_reg <= s_empty_next;
516	
517	    s_axis_tready_reg <= s_axis_tready_next;
518	
519	    m_axis_ptp_ts_reg <= m_axis_ptp_ts_next;
520	    m_axis_ptp_ts_tag_reg <= m_axis_ptp_ts_tag_next;
521	    m_axis_ptp_ts_valid_reg <= m_axis_ptp_ts_valid_next;
522	
523	    crc_state_reg[0] <= crc_state_next[0];
524	    crc_state_reg[1] <= crc_state_next[1];
525	    crc_state_reg[2] <= crc_state_next[2];
526	
527	    if (update_crc) begin
528	        crc_state_reg[3] <= crc_state_next[3];
529	    end
530	
531	    if (reset_crc) begin
532	        crc_state_reg[3] <= 32'hFFFFFFFF;
533	    end
534	
535	    xgmii_txd_reg <= xgmii_txd_next;
536	    xgmii_txc_reg <= xgmii_txc_next;
537	
538	    start_packet_reg <= start_packet_next;
539	    error_underflow_reg <= error_underflow_next;
540	
541	    if (rst) begin
542	        state_reg <= STATE_IDLE;
543	
544	        frame_reg <= 1'b0;
545	
546	        ifg_count_reg <= 8'd0;
547	        deficit_idle_count_reg <= 2'd0;
548	
549	        s_axis_tready_reg <= 1'b0;
550	
551	        m_axis_ptp_ts_valid_reg <= 1'b0;
552	
553	        xgmii_txd_reg <= {CTRL_WIDTH{XGMII_IDLE}};
554	        xgmii_txc_reg <= {CTRL_WIDTH{1'b1}};
555	
556	        start_packet_reg <= 1'b0;
557	        error_underflow_reg <= 1'b0;
558	    end
559	end
560	
561	endmodule
562	
563	`resetall
564

